def _legacy_mergeOrderings(orderings):
    merged = []
    for ordering in orderings:
        for item in ordering:
            if item not in merged:
                idx = next((i for i, x in enumerate(merged) if x > item), len(merged))
                merged.insert(idx, item)
    return merged

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    seen = set()
    result = []
    for cls in classes:
        if cls not in seen:
            seen.add(cls)
            result.append(cls)
            result.extend(minimalBases(cls.__bases__))
    return result

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    result = []
    for cls in classes:
        for base in cls.__bases__:
            if base not in result:
                result.append(base)
    return result

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    while True:
        new_classes = []
        for cls in classes:
            bases = set(cls.__bases__)
            if not bases.intersection(new_classes):
                new_classes.append(cls)
        if new_classes == classes:
            break
        classes = new_classes
    return classes

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    graph = {cls: set(cls.__bases__) for cls in classes}
    stack = [cls for cls in classes if not cls.__bases__]
    minimal = set()

    while stack:
       (cls,) = stack
        minimal.add(cls)
        stack += [base for base in graph[cls] if any(b not in minimal for b in base.__bases__)]

    return sorted(minimal)

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    minimal = []
    for cls in classes:
        bases = {cls}
        for b in cls.__bases__:
            while b in bases:
                bases.remove(b)
            bases.add(b)
            b = b.__bases__[0] if b.__bases__ else None
        minimal.extend(bases)
    return sorted(set(minimal))

