    """
    if context.error is None:
        context.error = {}
    if "x" not in context.error and "E" in self.fields:
        context.error["x"] = {"index": self.fields.index("E")}
    if "y" not in context.error and "t" in self.fields:
        context.error["y"] = {"index": self.fields.index("t")}
    if "z" not in context.error and "error_E_low" in self.fields:
