    for key, value in self.properties.items():
        if key not in context.value:
            context.value[key] = value
        else:
            context.value[key].update(value)

def _update_context(self, context):
    """Update *context* with the properties of this graph.

    *context.error* is appended with indices of errors.
    Example subcontext for a graph with fields "E,t,error_E_low":
    {"error": {"x_low": {"index": 2}}}.
    Note that error names are called "x", "y" and "z"
    (this corresponds to first three coordinates,
    if they are present), which allows to simplify plotting.
    Existing values are not removed
    from *context.value* and its subcontexts.

    Called on "destruction" of the graph (for example,
    in :class:`.ToCSV`). By destruction we mean conversion
    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.
    """
    if "error" in self._fields:
        errors = self._fields["error"]
        for i, error in enumerate(errors):
            if error:
                if "error" not in context:
                    context["error"] = {}
                if error == "error_E_low":
                    if "x_low" not in context["error"]:
                        context["error"]["x_low"] = {}
                    context["error"]["x_low"]["index"] = i + 1
                elif error == "error_E_high":
                    if "x_high" not in context["error"]:
                        context["error"]["x_high"] = {}
                    context["error"]["x_high"]["index"] = i + 1
                elif error == "error_T_low":
                    if "y_low" not in context["error"]:
                        context["error"]["y_low"] = {}
                    context["error"]["y_low"]["index"] = i + 1
                elif error == "error_T_high":
                    if "y_high" not in context["error"]:
                        context["error"]["y_high"] = {}
                    context["error"]["y_high"]["index"] = i + 1
                elif error == "error_Z":
                    if "z" not in context["error"]:
                        context["error"]["z"] = {}
                    context["error"]["z"]["index"] = i + 1
    # Merge existing and new values
    if "value" not in context:
        context["value"] = {}
    context["value"].update(self._fields)

