            errors.append({str(key): "Label key '{}' does not match the regex {}".format(str(key), key_regex.pattern)})
        if not isinstance(value, list):
            value = [value]
        for item in value:
            if not isinstance(item, str):
                errors.append({str(item): 'expected string or bytes-like object'})
            if not value_regex.match(item):
                errors.append({str(item): "Label value '{}' does not match the regex {}".format(item, value_regex.pattern)})

    if errors:
        raise ValidationError({'messages': errors})

