            if isinstance(value, dict):
                last_applied_manifest[key] = update_last_applied_manifest_dict_from_resp(last_applied_manifest[key], value, response[key])
            elif isinstance(value, list):
                last_applied_manifest[key] = update_last_applied_manifest_list_from_resp(last_applied_manifest[key], value, response[key])
