    last_applied_manifest if they are not yet present

    """
    for observer, resp in zip(observer_schema, response):
        if isinstance(observer, dict) and isinstance(resp, dict):
            update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer, resp)
        elif isinstance(observer, list) and isinstance(resp, list):
            update_last_applied_manifest_list_from_resp(last_applied_manifest, observer, resp)
