def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    for field in observer_schema:
        if field['type'] == 'list':
            if field['name'] in response:
                if field['name'] not in last_applied_manifest:
                    last_applied_manifest[field['name']] = []
                update_last_applied_manifest_list_from_resp(last_applied_manifest[field['name']], field['schema'], response[field['name']])
        elif field['type'] == 'dict':
            if field['name'] in response:
                if field['name'] not in last_applied_manifest:
                    last_applied_manifest[field['name']] = {}
                update_last_applied_manifest_dict_from_resp(last_applied_manifest[field['name']], field['schema'], response[field['name']])
        else:
            if field['name'] in response:
                if field['name'] not in last_applied_manifest:
                    last_applied_manifest[field['name']] = response[field['name']]
