    for file_path, file_info in fixity.items():
        if not isinstance(file_info, dict):
            raise ValueError("File info must be a dictionary")

        valid_file_info_keys = {'hash', 'size'}
        if not valid_file_info_keys.issubset(file_info.keys()):
            raise ValueError("Invalid file info keys")

        if file_path not in manifest_files:
            raise ValueError("File not listed in manifest: {}".format(file_path))

        if not isinstance(file_info['size'], int):
            raise ValueError("File size must be an integer")

        if not isinstance(file_info['hash'], str):
            raise ValueError("File hash must be a string")

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    if 'files' not in fixity:
        raise ValueError("Fixity block must contain 'files' key")

    valid_files = fixity['files']

    if not isinstance(valid_files, list):
        raise ValueError("The 'files' key must be a list of file paths")

    for file_path in valid_files:
        if file_path not in manifest_files:
            raise ValueError(f"File {file_path} not found in manifest")

