def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    suppl = None
    number = None

    issue_text = issue.strip()
    if issue_text:
        issue_parts = issue_text.split()
        for part in issue_parts:
            if 'suppl' in part.lower():
                suppl = part.strip('. ')
                if suppl.isdigit():
                    number = suppl
                    suppl = 'suppl'
                elif '-' in suppl:
                    parts = suppl.split('-')
                    if parts[0].isdigit():
                        number = parts[0]
                    if parts[1].isdigit():
                        number = parts[1]
                    suppl = 'suppl'
                elif 'spe' in part.lower():
                    suppl = 'spe'
                elif 'pr' in part.lower():
                    suppl = 'suppl pr'
            elif part.isdigit():
                number = part

    return number, suppl

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    if debug:
        from verboselogs import VerboseLogger
        logger = VerboseLogger(self.__class__.__name__)
        logger.debug(f"pretty({indent=}, {debug=})")

    # Assuming self is a container with items that need to be pretty-printed
    output = []
    for i, item in enumerate(self):
        if i > 0:
            output.append('\n' + ' ' * indent)
        output.append(str(item))

    return '\n'.join(output)

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    if debug:
        indent += 2

    pretty_representation = " " * indent + str(self) + "\n"
    for attribute in dir(self):
        if not attribute.startswith("__"):
            value = getattr(self, attribute)
            if isinstance(value, (list, tuple, set)):
                pretty_representation += " " * (indent + 2) + attribute + ":\n"
                for item in value:
                    pretty_representation += " " * (indent + 4) + str(item) + "\n"
            elif isinstance(value, dict):
                pretty_representation += " " * (indent + 2) + attribute + ":\n"
                for key, val in value.items():
                    pretty_representation += " " * (indent + 4) + str(key) + ": " + str(val) + "\n"
            else:
                pretty_representation += " " * (indent + 2) + attribute + ": " + str(value) + "\n"

    return pretty_representation

