def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def apply_absorption(expr):
        if expr.is_binary('&'):
            left, right = expr.operands
            if left == right:
                return left
            elif left.is_binary('|') and left.operands[0] == expr:
                return expr
            elif left.is_binary '&' and left.operands[0] == expr:
                return expr
        if expr.is_binary('|'):
            left, right = expr.operands
            if left == right:
                return left
            elif left.is_binary('&') and left.operands[0] == expr:
                return expr
            elif left.is_binary '|' and left.operands[0] == expr:
                return expr
        return expr

    def apply_negative_absorption(expr):
        if expr.is_binary('&'):
            left, right = expr.operands
            if left.is_binary('~') and left.operands[0] == expr.operands[1]:
                return right
            elif right.is_binary('~') and right.operands[0] == expr.operands[0]:
                return left
        if expr.is_binary('|'):
            left, right = expr.operands
            if left.is_binary('~') and left.operands[0] == expr.operands[1]:
                return left
            elif right.is_binary('~') and right.operands[0] == expr.operands[0]:
                return right
        return expr

    result = []
    for expr in args:
        absorbed_expr = apply_absorption(expr)
        result.append(absorbed_expr)
        result.append(apply_negative_absorption(absorbed_expr))
    return result

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::
        A & (A | B) = A, A | (A & B) = A

    Negative absorption::
        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if isinstance(arg, tuple):
            # Handle binary operations
            left, op, right = arg
            if op == '&':
                if left == right:
                    new_args.append(left)
                elif neg_absorption(left, right):
                    new_args.append(left)
            elif op == '|':
                if left == right:
                    new_args.append(left)
                elif neg_absorption(left, right):
                    new_args.append(left)
        else:
            new_args.append(arg)
    return new_args

def neg_absorption(left, right):
    # Check for negative absorption
    if isinstance(left, tuple) and isinstance(right, tuple):
        left_left, left_op, left_right = left
        right_left, right_op, right_right = right
        if left_op == '~':
            if left_left == right_left and right_op == '&':
                return True
            elif left_left == right_left and right_op == '|':
                return True
        elif right_op == '~':
            if right_left == left_left and left_op == '&':
                return True
            elif right_left == left_left and left_op == '|':
                return True
    return False

