    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    root_inventory = self.get_root_inventory()
    content_digests = {}
    for version_dir in version_dirs:
        inventory_path = os.path.join(self.root_dir, version_dir, 'inventory.json')
        if not os.path.exists(inventory_path):
            raise ValueError(f"Inventory file for version {version_dir} does not exist.")
        with open(inventory_path, 'r') as h:
            inventory = json.load(h)
        if not isinstance(inventory, dict):
            raise ValueError(f"Inventory file for version {version_dir} is not a valid dictionary.")
        for key, value in inventory.items():
            if key in content_digests and content_digests[key] != value:
                raise ValueError(f"Content digest for key {key} differs between root and version {version_dir}.")
            content_digests[key] = value
        if version_dir != version_dirs[0]:
            prev_inventory_path = os.path.join(self.root_dir, version_dirs[version_dirs.index(version_dir) - 1], 'inventory.json')
            with open(prev_inventory_path, 'r') as h:
                prev_inventory = json.load(h)
            if inventory != prev_inventory:
                raise ValueError(f"Inventory for version {version_dir} does not match the previous version.")
    return content_digests

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    # %%%%%%%%%%%%%%%%%%%%%%%%%%%%% Verification of path type %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    import os

    try:
        if os.path.isfile(path):
            return 'file'
        elif os.path.isdir(path):
            namaste_file = os.path.join(path, '0=*')
            if os.path.isfile(namaste_file):
                with open(namaste_file, 'r') as f:
                    first_line = f.readline().strip()
                    if first_line == 'root':
                        return 'root'
                    elif first_line == 'object':
                        return 'object'
    except Exception as e:
        return str(e)

    return 'unknown'

