        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        with open(path + '/0=*', 'r') as f:
            namaste_content = f.read().strip()
            if namaste_content == 'OCFL 1.0':
                if 'storageconfig.json' in f.name:
                    return 'root'
                elif 'inventory.json' in f.name:
                    return 'object'
            else:
                return 'unknown format'
    except FileNotFoundError:
        if path.count('/') == 1:
            return 'object'
        elif path.count('/') == 2:
            return 'file'
    except Exception as e:
        return str(e)

def find_path_type(path):
