def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    parsed_args = {}
    remaining_args = list(unparsed_arguments)

    for subparser_name, subparser in subparsers.items():
        # Find the first subparser that can parse the remaining arguments
        subparser_actions = subparser._actions
        parser_consumed_args = []
        for action in subparser_actions:
            if action.dest != "help":
                if not parser_consumed_args:
                    parsed_args[subparser_name], remaining_args = \
                        subparser.parse_known_args(remaining_args)
                    for arg in parsed_args[subparser_name].__dict__:
                        if getattr(parsed_args[subparser_name], arg) is not None:
                            parser_consumed_args.append(arg)
                else:
                    parser_consumed_args.extend(action.option_strings)

    return parsed_args, remaining_args

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    parsed_args = {}
    remaining_args = []
    for subparser_name, subparser in subparsers.items():
        try:
            resultNamespace, remaining = subparser.parse_known_args(unparsed_arguments)
            if resultNamespace:
                parsed_args[subparser_name] = resultNamespace
                unparsed_arguments = remaining
        except SystemExit:
            # Ignore SystemExit exceptions raised by argparse's error handling
            continue
    return parsed_args, unparsed_arguments

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_dict = {}
    remaining_args = list(unparsed_arguments)

    for name, parser in subparsers.items():
        position = 0
        while position < len(remaining_args):
            try:
                namespace, remaining = parser.parse_known_args(remaining_args[position:])
                parsed_dict[name] = namespace
                remaining_args = position + remaining
                position = len(remaining_args)  # Move to the end of the list
            except Exception as e:
                position += 1

    return parsed_dict, remaining_args

