    return parsed_args, remaining_args

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size
    """
    size = size.strip()
    unit_map = { 'K': 1000, 'M': 1000000, 'G': 1000000000, 'T': 1000000000000 }
    for suffix, multiplier in unit_map.items():
        if size.endswith(suffix):
            return int(float(size[:-1]) * multiplier)
    return int(size)

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.upper()
    if size.endswith('B'):
        return int(size[:-1])
    elif size.endswith('K'):
        return int(float(size[:-1]) * 1024)
    elif size.endswith('M'):
        return int(float(size[:-1]) * (1024 ** 2))
    elif size.endswith('G'):
        return int(float(size[:-1]) * (1024 ** 3))
    elif size.endswith('T'):
        return int(float(size[:-1]) * (1024 ** 4))
    elif size.endswith('P'):
        return int(float(size[:-1]) * (1024 ** 5))
    elif size.endswith('E'):
        return int(float(size[:-1]) * (1024 ** 6))
    elif size.endswith('Z'):
        return int(float(size[:-1]) * (1024 ** 7))
    elif size.endswith('Y'):
        return int(float(size[:-1]) * (1024 ** 8))
    else:
        raise ValueError(f"Invalid size format: {size}")

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size_str = size.upper()
    if size_str[-1].isalpha():
        size_unit = size_str[-1]
        size_value = float(size_str[:-1])
        if size_unit == 'B':
            return int(size_value)
        elif size_unit == 'K':
            return int(size_value * 1024)
        elif size_unit == 'M':
            return int(size_value * 1024 * 1024)
        elif size_unit == 'G':
            return int(size_value * 1024 * 1024 * 1024)
        elif size_unit == 'T':
            return int(size_value * 1024 * 1024 * 1024 * 1024)
    return int(size_str)

