def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet must not be empty")

    base = len(alphabet)
    if number < 0:
        raise ValueError("Number must be non-negative")

    if padding is None:
        padding = 0

    result = ""
    while number > 0:
        result = alphabet[number % base] + result
        number //= base

    return result.zfill(padding)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number == 0:
        return alphabet[0]

    base = len(alphabet)
    result = []

    while number > 0:
        result.append(alphabet[number % base])
        number //= base

    if padding and len(result) < padding:
        result.extend([alphabet[0]] * (padding - len(result)))

    return ''.join(reversed(result))

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet cannot be empty.")

    if number == 0:
        return alphabet[0] if alphabet else ''

    base = len(alphabet)
    digits = []

    while number:
        digits.append(alphabet[number % base])
        number //= base

    if padding and len(digits) < padding:
        digits.extend([alphabet[0]] * (padding - len(digits)))

    return ''.join(reversed(digits))

