def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency.lower() == "always":
        return None
    units = {
        "second": "seconds",
        "minute": "minutes",
        "hour": "hours",
        "day": "days",
        "week": "weeks",
        "month": "months",
        "year": "years"
    }
    parts = frequency.split()
    if len(parts) != 2:
        raise ValueError("Invalid frequency format")
    try:
        num = int(parts[0])
    except ValueError:
        raise ValueError("Invalid frequency format")
    unit = parts[1].strip('s')
    if unit not in units:
        raise ValueError("Invalid frequency format")
    return getattr(datetime.timedelta, units[unit])(**{unit: num})

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency.lower() == "always":
        return None

    freq_parts = frequency.split()
    if len(freq_parts) != 2:
        raise ValueError("Invalid frequency format")

    try:
        value = int(freq_parts[0])
    except ValueError:
        raise ValueError("Invalid frequency format")

    unit = freq_parts[1].lower()
    if unit not in ["second", "seconds", "minute", "minutes", "hour", "hours", "day", "days", "week", "weeks", "month", "months", "year", "years"]:
        raise ValueError("Invalid frequency format")

    if unit.startswith('second'):
        return datetime.timedelta(seconds=value)
    elif unit.startswith('minute'):
        return datetime.timedelta(minutes=value)
    elif unit.startswith('hour'):
        return datetime.timedelta(hours=value)
    elif unit.startswith('day'):
        return datetime.timedelta(days=value)
    elif unit.startswith('week'):
        return datetime.timedelta(weeks=value)
    elif unit.startswith('month'):
        return datetime.timedelta(days=value * 30)  # Approximation for month
    elif unit.startswith('year'):
        return datetime.timedelta(days=value * 365)  # Approximation for year

def parse_frequency(frequency):
    import datetime
    if frequency is None or frequency == "always":
        return None
    try:
        numbers = [int(s) for s in frequency.split() if s.isdigit()]
        units = [s for s in frequency.split() if s.isalpha()]
        if len(numbers) != len(units):
            raise ValueError("Invalid frequency format")
        timedelta_dict = {
            'year': 'years',
            'month': 'months',
            'week': 'weeks',
            'day': 'days',
            'hour': 'hours',
            'minute': 'minutes',
            'second': 'seconds'
        }
        timedelta_args = {}
        for number, unit in zip(numbers, units):
            if unit not in timedelta_dict or number <= 0:
                raise ValueError("Invalid frequency format")
            timedelta_args[timedelta_dict[unit]] = number
        return datetime.timedelta(**timedelta_args)
    except ValueError as e:
        raise ValueError("Cannot parse frequency: " + e)

def make_find_paths(find_paths):
    '''
    Given a sequence of path fragments or patterns as passed to `--find`, transform all path
    fragments into glob patterns. Pass through existing patterns untouched.

    For example, given find_paths of:

      ['foo.txt', 'pp:root/somedir']

    ... transform that into:

      ['sh:**/*foo.txt*/**', 'pp:root/somedir']
    '''

    def is_pattern(path):
        return ':' in path

    def make_glob_pattern(path):
        # Split the path into parts
        parts = path.split('/')
        new_parts = []
        for part in parts:
            if is_pattern(part):
                new_parts.append(part)
            else:
                new_parts.append(f'*{part}*')
        return 'sh:**/*{}/**'.format('/*'.join(new_parts))

    return [make_glob_pattern(path) if not is_pattern(path) else path for path in find_paths]

