def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    for command in commands:
        full_command = [command] + args
        try:
            if hide_stderr:
                output = subprocess.check_output(full_command, cwd=cwd, stderr=subprocess.STDOUT, env=env)
            else:
                output = subprocess.check_output(full_command, cwd=cwd, env=env)

            if verbose:
                print(f"Output: {output.decode()}")

            if not hide_stderr:
                return output
        except subprocess.CalledProcessError as e:
            if verbose:
                print(f"Error: {e.output.decode()}")
            raise subprocess.CalledProcessError(e.returncode, full_command, output=e.output)

