def find_roots(graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    if roots is None:
        roots = set()

    nodes = list(graph.subjects(predicate=prop))
    seen = set()

    for node in nodes:
        if node not in seen:
            stack = [node]
            while stack:
                current = stack.pop()
                if current not in seen:
                    seen.add(current)
                    stack.extend(graph.subjects(predicate=prop, object=current))

    roots.update(nodes - seen)
    return roots

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()
    for s, p, o in graph:
        if p == prop:
            roots.discard(o)
            if o not in roots:
                roots.add(s)
    return roots

def find_roots(graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader
    """

    if roots is None:
        roots = set()

    for s, p, o in graph:
        if p == prop:
            roots.discard(o)

    for s, p, o in graph:
        if p == prop and o not in roots:
            roots.add(s)

    return roots

