                                                 lineno=0, msg=f'File {config_filename} not found'))
        except toml.TomlDecodeError as e:
            log_records.append(logging.LogRecord(level=logging.ERROR, pathname='load_configurations', 
                                                 lineno=0, msg=f'TOML decode error in {config_filename}: {e}'))

    return config_dict, log_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    config_dict = {}
    log_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as file:
                config = toml.loads(file.read())
                if overrides:
                    config.update(overrides)

                if resolve_env:
                    config = resolve_environment_variables(config)

                config_dict[filename] = config
        except FileNotFoundError:
            log.error(f"Configuration file not found: {filename}")
            log_records.append(logging.LogRecord('load_configurations', logging.ERROR, filename, -1, f"Configuration file not found: {filename}", {}, 0))
        except toml.TomlDecodeError as e:
            log.error(f"Error parsing configuration file {filename}: {e}")
            log_records.append(logging.LogRecord('load_configurations', logging.ERROR, filename, -1, f"Error parsing configuration file {filename}: {e}", {}, 0))
        except Exception as e:
            log.error(f"Unexpected error loading configuration file {filename}: {e}")
            log_records.append(logging.LogRecord('load_configurations', logging.ERROR, filename, -1, f"Unexpected error loading configuration file {filename}: {e}", {}, 0))

    return config_dict, log_records

