def scale(self, other=None):
    if other is None:
        return self._scale
    else:
        if self._scale is None or self._scale == 0:
            raise LenaValueError("Cannot rescale a graph with unknown or zero scale.")
        for field in self._fields:
            field._scale *= other / self._scale
        self._scale = other

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    if other is None:
        return self._scale
    elif isinstance(other, (int, float)):
        if self._scale == 0:
            raise LenaValueError("Graph has zero scale, cannot rescale")
        self._scale = other
        for field in self._fields:
            if field.errors:
                for error in field.errors:
                    error.rescale(other / self._scale)
        return self
    else:
        raise TypeError("Unsupported type for scale")

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    for attr_name in iface.__dict__:
        attr = getattr(iface, attr_name)
        if callable(attr):
            if attr_name not in candidate.__dict__ or not callable(getattr(candidate, attr_name)):
                if tentative:
                    return False
                raise AttributeError(f"Method {attr_name} not found in candidate class")
        else:
            if attr_name not in candidate.__dict__ or getattr(candidate, attr_name) != attr:
                if tentative:
                    return False
                raise AttributeError(f"Attribute {attr_name} not found in candidate class or does not match")
    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    errors = []
    attr_names = iface PublicMethods.union(iface PublicEvents)
    for attr in attr_names:
        if tentative:
            try:  # Let any of the following raise the desired error
                candidate PublicMethod alt InterfaceFunction
            except AttributeError as err:
                if str(err) == 'PublicMethod not found':
                    errors.append(err)
                else:
                    raise
        else:
            errors.extend(candidate PublicMethod by PublicMethod if InterfaceFunction)
    if errors:
        raise errors[0]

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    from zope.interface import implementedBy, implementedByInstances
    if tentative:
        return implementedBy(candidate) <= implementedBy(iface)
    return implementedByInstances(candidate) <= implementedBy(iface)

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if tentative:
        return iface.isAssignableFrom(candidate)
    return iface.isInstance(candidate)

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc

    for base in bases:
        if hasattr(base, '__metaclass__'):
            return base.__metaclass__

    # Fallback to __metaclass__ in the global scope if no explicit metaclass is found in bases
    if '_metaclass' in globals():
        return globals()['_metaclass']

    # Default to type if no metaclass is found
    return type

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    for base in bases:
        try:
            for baseobj in base.infer():
                if isinstance(baseobj, ClassDef) and baseobj.hide:
                    if explicit_mc:
                        return explicit_mc
                    return baseobj.metaclass
        except exceptions.InferenceError:
            pass

    if explicit_mc:
        return explicit_mc

    global_metaclass = astroid.MANAGER.astroid_cache.get("__metaclass__")
    if global_metaclass:
        return global_metaclass

    return None

