import datetime
from dateutil.tz import tzutc, tzoffset

def isoparse(dt_str):
    """Parse an ISO-8601 datetime string into a datetime.datetime."""

    def parse_date(date_str):
        if 'W' in date_str:
            year, week, day = map(int, date_str.split('W'))
            if day:
                return datetime.datetime.strptime(f'{year}-01-01', '%Y-%m-%d') + datetime.timedelta(weeks=week-1, days=day-1)
            else:
                return datetime.datetime.strptime(f'{year}-01-01', '%Y-%m-%d') + datetime.timedelta(weeks=week-1)
        else:
            return datetime.datetime.strptime(date_str, '%Y-%m-%d')

    def parse_time(time_str):
        return datetime.datetime.strptime(time_str, '%H:%M:%S.%f')

    def parse_offset(offset_str):
        if offset_str == 'Z':
            return tzutc()
        if offset_str.startswith('±'):
            sign = offset_str[0]
            offset_str = offset_str[1:]
            hours, minutes = map(int, offset_str.split(':'))
            return tzoffset(sign + offset_str, hours * 3600 + minutes * 60)
        return None

    def parse_datetime_components(date_str, time_str, offset_str):
        date_components = date_str.split('-')
        if len(date_components) == 1:
            year = int(date_components[0])
            month = day = 1
        elif len(date_components) == 2:
            year, month = map(int, date_components)
            day = 1
        else:
            year, month, day = map(int, date_components)

        time_components = time_str.split(':')
        if len(time_components) == 1:
            hour = int(time_components[0])
            minute = second = microsecond = 0
        elif len(time_components) == 2:
            hour, minute = map(int, time_components)
            second = microsecond = 0
        elif len(time_components) == 3:
            hour, minute, second = map(int, time_components)
            microsecond = 0
        else:
            hour, minute, second, microsecond = map(int, time_components[3].split('.'))

        dt = datetime.datetime(year, month, day, hour, minute, second, microsecond)
        if offset_str:
            dt = dt.replace(tzinfo=parse_offset(offset_str))
        return dt

   (date_str, time_str, offset_str) = dt_str.split('T')
    date_str = date_str.replace('-', '')
    time_str = time_str.replace(':', '')
    return parse_datetime_components(date_str, time_str, offset_str)

