def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    code_mode = False
    new_text = []
    tag_pattern = re.compile(r'\b(tag|feature|bug)\b')

    for line in text.split('\n'):
        if '```' in line:
            code_mode = not code_mode
        if not code_mode:
            matches = tag_pattern.finditer(line)
            for match in matches:
                tag = match.group().strip()
                tags.add(tag)
                if replacer:
                    new_text.append(replacer(tag))
                else:
                    new_text.append(tag)
            if not replacer:
                new_text.append(line)
        else:
            new_text.append(line)

    if not replacer:
        return tags, '\n'.join(new_text)
    else:
        return tags, '\n'.join(new_text)

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""

    def add_attributes(url):
        return f"target='_blank' href='{url}'"

    def linkify(text, buildroot, memoized_urls):
        """Augment text by heuristically finding URL and file references and turning them into links.

        :param string s: The text to insert links into.
        :param dict memoized_urls: A cache of text to links so repeated substitutions don't require
                                   additional file stats calls.
        """
        def memoized_to_url(m):
            # to_url uses None to signal not to replace the text,
            # so we use a different sentinel value.
            value = memoized_urls.get(m.group(0), _NO_URL)
            if value is _NO_URL:
                value = to_url(m)
                memoized_urls[m.group(0)] = value
            return value

        def to_url(m):
            if m.group(1):
                return m.group(0)  # It's an http(s) url.
            path = m.group(0)

            if path.startswith('/'):
                path = os.path.relpath(path, buildroot)
            elif path.startswith('..'):
                # The path is not located inside the buildroot, so it's definitely not a BUILD file.
                return None
            else:
                # The path is located in the buildroot: see if it's a reference to a target in a BUILD file.
                parts = path.split(':')
                if len(parts) == 2:
                    putative_dir = parts[0]
                else:
                    putative_dir = path
                if os.path.isdir(os.path.join(buildroot, putative_dir)):
                    build_files = list(BuildFile.get_build_files_family(
                        FileSystemProjectTree(buildroot),
                        putative_dir))
                    if build_files:
                        path = build_files[0].relpath
                    else:
                        return None

            if os.path.exists(os.path.join(buildroot, path)):
                # The reporting server serves file content at /browse/<path_from_buildroot>.
                return '/browse/{}'.format(path)
            else:
                return None

        def maybe_add_link(url, text):
            if url:
                return f'<a {add_attributes(url)}>{text}</a>'
            else:
                return text

        return _PATH_RE.sub(lambda m: maybe_add_link(memoized_to_url(m), m.group(0)), text)

    return linkify(text, self.buildroot, self.memoized_urls)

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""

    def add_attrs(url):
        return ' target="_blank"'

    def linkify(m):
        url = m.group(0)
        if '://' in url:
            return f'<a{add_attrs(url)}>{url}</a>'
        return f'<a{add_attrs(f"http://{url}")}>http://{url}</a>'

    import re
    link_pattern = re.compile(r'\b\w+\.\w+\b')
    return link_pattern.sub(linkify, text)

